mapper.select:
select t.pa_num,t.pa_num paNum,t.machine_code,t.machine_code machineCode,t.car_inout,t.car_inout
carInout,t.photo_jpg,t.photo_jpg photoJpg,t.car_num,t.car_num carNum,t.remark,t.status_cd,t.status_cd
statusCd,t.ci_id,t.ci_id ciId,t.inout_id,t.inout_id inoutId,t.machine_id,t.machine_id
machineId,t.car_type,t.car_type carType,t.pa_id,t.pa_id paId,t.state,t.community_id,t.community_id
communityId,t.open_time,t.open_time openTime,t.in_time inTime,t.car_type_name,t.car_type_name carTypeName,
td.name stateName,tcfc.fee_name feeName,tcfc.config_id configId,cip.create_time payTime,t.unlicense
from car_inout t
left join t_dict td on t.state = td.status_cd and td.table_columns='state' and td.table_name = 'car_inout'
left join parking_area pa on t.pa_id = pa.pa_id and pa.status_cd = '0'
left join temp_car_fee_config tcfc on pa.pa_id = tcfc.pa_id and tcfc.status_cd = '0'
left join car_inout_payment cip on t.inout_id = cip.inout_id and cip.status_cd = '0'
where 1 =1

    and t.pa_num= #{paNum}


    and t.machine_code= #{machineCode}


    and t.car_inout= #{carInout}


    and t.photo_jpg= #{photoJpg}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.ci_id= #{ciId}


    and t.inout_id= #{inoutId}


    and t.machine_id= #{machineId}


    and t.car_type= #{carType}


    and t.pa_id= #{paId}


    and t.pa_id in

        #{item}



    and t.car_num = #{carNum}


    and t.car_num like concat('%',#{carNum},'%')


    and t.state= #{state}


    and t.state in

        #{item}



    and t.community_id= #{communityId}


    and t.open_time= #{openTime}


    and t.car_type_name= #{carTypeName}

order by t.create_time desc

    limit #{page}, #{row}

