select t.inout_id,t.inout_id inoutId,t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code
machineCode,t.car_inout,t.car_inout carInout,t.pa_id,t.pa_id paId,t.ci_id
ciId,t.car_num,t.car_num carNum,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id communityId,t.state,
t.in_time inTime,t.open_time openTime,
(select max(cip.real_charge) from car_inout_payment cip where cip.inout_id = t.inout_id and cip.community_id = t.community_id)  realCharge,
t.pa_id paId,td.name stateName,t.remark,t.car_type carType
,t.pa_num paNum,tcfc.fee_name feeName,tcfc.config_id configId,t.car_type_name carTypeName,t.state inState,t.photo_jpg photoJpg,t.unlicense,b.machine_name machineName
from car_inout t
left join car_inout_payment cip on cip.inout_id = t.inout_id and cip.community_id = t.community_id
left join t_dict td on t.state = td.status_cd and td.table_columns='state' and td.table_name = 'car_inout'
left join parking_area pa on t.pa_id = pa.pa_id and pa.status_cd = '0'
left join temp_car_fee_config tcfc on pa.pa_id = tcfc.pa_id and tcfc.status_cd = '0'
left join barrier b on t.machine_id = b.machine_id and b.community_id = t.community_id
where 1 =1


    and t.inout_id= #{inoutId}


    and t.machine_id= #{machineId}


    and b.machine_name like concat('%', #{machineName},'%')


    and t.machine_code= #{machineCode}


    and t.car_inout= #{carInout}


    and t.pa_id= #{paId}


    and t.pa_id in

        #{item}



    and t.detail_id= #{detailId}


    and t.car_num like concat('%',#{carNum},'%')


    and t.car_type= #{carType}


    and t.state= #{state}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.create_time > #{startTime}


    and t.create_time < #{endTime}

order by t.open_time desc

    limit #{page}, #{row}

